<div style="display:flex;justify-content:space-between;align-items:center"><div><h2 style="margin-bottom:0">Kitchen display</h2><p class="muted">Incoming orders update automatically. Keep this screen open with sound enabled.</p></div><button id="sound" class="ghost">Enable sound</button></div>
<section style="display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:16px">@forelse($orders as $order)@php($prep=$order->items->max(fn($item)=>$item->menuItem?->preparation_minutes??15))<article class="card" style="border-top:6px solid {{ $order->status==='confirmed'?'#d8552f':($order->status==='preparing'?'#d39a31':'#225c48') }}"><div style="display:flex;justify-content:space-between;align-items:start"><div><span class="pill {{ $order->status }}">{{ $order->status }}</span><h2 style="font-size:30px;margin:6px 0">{{ $order->tableSession->diningTable->table_code }}</h2><b>{{ $order->order_number }}</b></div><div class="right"><div class="timer value" data-start="{{ ($order->confirmed_at??$order->created_at)->timestamp }}" data-minutes="{{ $prep }}">00:00</div><small class="muted">target {{ $prep }} min</small></div></div><hr style="border:0;border-top:1px solid var(--line)"><table>@foreach($order->items as $item)<tr><td class="value" style="font-size:22px;width:45px">{{ $item->quantity }}×</td><td><b>{{ $item->item_name_snapshot }}</b>@if($item->special_instruction)<div style="color:#a13821;font-weight:700">{{ $item->special_instruction }}</div>@endif</td></tr>@endforeach</table>@if($order->customer_note)<p class="errors" style="margin-top:10px"><b>Customer note:</b> {{ $order->customer_note }}</p>@endif<div class="actions" style="margin-top:14px">@if($order->status==='confirmed')<form method="post" action="/kitchen/orders/{{ $order->id }}/preparing">@csrf<button>Accept & start preparing</button></form>@elseif($order->status==='preparing')<form method="post" action="/kitchen/orders/{{ $order->id }}/ready">@csrf<button>Mark ready</button></form>@elseif($order->status==='ready')<form method="post" action="/kitchen/orders/{{ $order->id }}/served">@csrf<button>Mark served</button></form>@endif</div></article>@empty<div class="card"><h2>Queue clear</h2><p class="muted">New confirmed orders will appear automatically.</p></div>@endforelse</section>
<script>let fingerprint=@json($orders->map(fn($o)=>[$o->id,$o->status,$o->updated_at?->timestamp]));let sound=false;document.querySelector('#sound').onclick=()=>{sound=true;beep();document.querySelector('#sound').textContent='Sound enabled'};function beep(){if(!sound)return;const c=new AudioContext(),o=c.createOscillator(),g=c.createGain();o.frequency.value=880;o.connect(g);g.connect(c.destination);g.gain.setValueAtTime(.18,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+.45);o.start();o.stop(c.currentTime+.45)}function timers(){document.querySelectorAll('.timer').forEach(el=>{const elapsed=Math.floor(Date.now()/1000)-Number(el.dataset.start),target=Number(el.dataset.minutes)*60,remaining=target-elapsed,late=remaining<0,n=Math.abs(remaining);el.textContent=(late?'+':'')+String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');el.style.color=late?'#b83222':''})}timers();setInterval(timers,1000);setInterval(async()=>{try{const data=await fetch('/kitchen/snapshot',{headers:{Accept:'application/json'}}).then(r=>r.json()),next=JSON.stringify(data),old=JSON.stringify(fingerprint);if(next!==old){if(data.length>fingerprint.length)beep();location.reload()}}catch(e){}},4000);</script>@endsection
